(400708, 35064, 10848, '<td valign="top">Great concept..wonderful detail</td>', 'Great concept..wonderful detail', '2003-08-27 03:36:39.000000', NULL, 1),
(400710, 35162, 10848, '<td valign="top">The approach to a shot and to portray the message of a photo to me is the foundation of a photo..speaks a thousand word...good angle..the title is great..the angle makes the model seem larger than life.I like it....good job!</td>', 'The approach to a shot and to portray the message of a photo to me is the foundation of a photo..speaks a thousand word...good angle..the title is great..the angle makes the model seem larger than life.I like it....good job!', '2003-08-27 03:40:06.000000', NULL, 1),
