(401124, 35074, 6008, '<td valign="top">Giving the tool a human element is a nice touch and adds more character to it. The choice of toning is also good and adds to that mood and character. At first glance the hands seem to be the focus, probably because they are more center and lighter, but hands are in themselves a tool and so it blends well. The only thing I''m not too keen on appears to be a DOF(?) issue on his lower right leg. The blur is a little distracting and it also affects the head of the tool.</td>', 'Giving the tool a human element is a nice touch and adds more character to it. The choice of toning is also good and adds to that mood and character. At first glance the hands seem to be the focus, probably because they are more center and lighter, but hands are in themselves a tool and so it blends well. The only thing I''m not too keen on appears to be a DOF(?) issue on his lower right leg. The blur is a little distracting and it also affects the head of the tool.', '2003-08-27 11:40:23.000000', NULL, 1),
(401125, 35003, 11111, '<td valign="top">You have a good idea here subject-matter-wise, but I think there''s too much going on in here.  My eye is drawn to the leash because it seems highlighted. Was that your intention? I''m not sure where to focus.</td>', 'You have a good idea here subject-matter-wise, but I think there''s too much going on in here.  My eye is drawn to the leash because it seems highlighted. Was that your intention? I''m not sure where to focus.', '2003-08-27 11:40:27.000000', NULL, 1),
(401126, 35065, 3724, '<td valign="top">love your collection, i have some similar pieces.  the sharpening steel, grater and scale appear to be the same.  i am wondering about the partial image of what appears as a turnscrew on a press?</td>', 'love your collection, i have some similar pieces.  the sharpening steel, grater and scale appear to be the same.  i am wondering about the partial image of what appears as a turnscrew on a press?', '2003-08-27 11:40:41.000000', NULL, 1),
(401127, 34688, 6624, '<td valign="top">this lacks clarity</td>', 'this lacks clarity', '2003-08-27 11:40:43.000000', NULL, 1),
(401128, 34624, 11111, '<td valign="top">Nice shot! Good exposure and it''s great to see it in b&amp;w.</td>', 'Nice shot! Good exposure and it''s great to see it in b&w.', '2003-08-27 11:41:03.000000', NULL, 1),
(401131, 35021, 6624, '<td valign="top">this is interesting - I wish the welder''s mask were a little more evident.  I assume it was sacrificed to the ''spark''</td>', 'this is interesting - I wish the welder''s mask were a little more evident.  I assume it was sacrificed to the ''spark''', '2003-08-27 11:42:12.000000', NULL, 1),
(401132, 35071, 11111, '<td valign="top">This is great! Good composition, focus, color is wonderful. Think I''d like to see it cropped in more tightly around the tools while retaining the door. The stuff to the right is distracting, though those are tools, too.</td>', 'This is great! Good composition, focus, color is wonderful. Think I''d like to see it cropped in more tightly around the tools while retaining the door. The stuff to the right is distracting, though those are tools, too.', '2003-08-27 11:43:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(401133, 34573, 11111, '<td valign="top">Perfect product shot. You''ve got that studio lighting thing going on. It''s marvelous though.</td>', 'Perfect product shot. You''ve got that studio lighting thing going on. It''s marvelous though.', '2003-08-27 11:44:04.000000', NULL, 1),
(401136, 35210, 11111, '<td valign="top">I like that this is on the dark side. Gives it more of an industrial, dirty feel. Nice composition and focus on the tool.</td>', 'I like that this is on the dark side. Gives it more of an industrial, dirty feel. Nice composition and focus on the tool.', '2003-08-27 11:45:17.000000', NULL, 1),
(401137, 35200, 6008, '<td valign="top">The warm tones really make this image. It''s an abstract so I''m not sure what it is, but the jagged lines along with the title at least hints at some sort of cutting tool. The lighting is really good, adding to the warm tones to make a very appealing image. The textures and level of DOF is really good too, with the subtle shadow on the blade a nice touch. Not a stereotypical image for this challenge, but a nice refreshing one!</td>', 'The warm tones really make this image. It''s an abstract so I''m not sure what it is, but the jagged lines along with the title at least hints at some sort of cutting tool. The lighting is really good, adding to the warm tones to make a very appealing image. The textures and level of DOF is really good too, with the subtle shadow on the blade a nice touch. Not a stereotypical image for this challenge, but a nice refreshing one!', '2003-08-27 11:45:39.000000', NULL, 1),
(401138, 34735, 11111, '<td valign="top">Nice, bright shot. I can see all the details. Good one.</td>', 'Nice, bright shot. I can see all the details. Good one.', '2003-08-27 11:45:58.000000', NULL, 1),
(401140, 35243, 11111, '<td valign="top">Great title. It''s nice to see something creative! I also like the grittiness of the tool. I''d like to see it a bit brighter though.</td>', 'Great title. It''s nice to see something creative! I also like the grittiness of the tool. I''d like to see it a bit brighter though.', '2003-08-27 11:46:51.000000', NULL, 1),
(401141, 35157, 8229, '<td valign="top">what is this??</td>', 'what is this??', '2003-08-27 11:47:15.000000', NULL, 1),
(401143, 35003, 8229, '<td valign="top">is that a yorkshire terrier?? i have one and he looks exactly like that!  his name is otis campbell.</td>', 'is that a yorkshire terrier?? i have one and he looks exactly like that!  his name is otis campbell.', '2003-08-27 11:48:29.000000', NULL, 1),
(401146, 35094, 11111, '<td valign="top">Interesting idea with the way you framed this. Lighting is good enough to highlight the screw and part of the driver, but the whole center part disappears and I''d like to see it.</td>', 'Interesting idea with the way you framed this. Lighting is good enough to highlight the screw and part of the driver, but the whole center part disappears and I''d like to see it.', '2003-08-27 11:49:07.000000', NULL, 1),
(401147, 34547, 8229, '<td valign="top">too funny!!</td>', 'too funny!!', '2003-08-27 11:49:27.000000', NULL, 1),
(401148, 34550, 11111, '<td valign="top">Pretty! Original! I like this a ton.</td>', 'Pretty! Original! I like this a ton.', '2003-08-27 11:49:45.000000', NULL, 1),
(401151, 34966, 11111, '<td valign="top">Wonderful. Perfectly in focus. Great b&amp;w balance.</td>', 'Wonderful. Perfectly in focus. Great b&w balance.', '2003-08-27 11:51:53.000000', NULL, 1),
(401153, 35136, 4518, '<td valign="top">That is not a spanner, that is an open ended adjustable cresent wrench</td>', 'That is not a spanner, that is an open ended adjustable cresent wrench', '2003-08-27 11:53:16.000000', NULL, 1),
(401154, 35120, 4008, '<td valign="top">Should have cleaned it more thoroughly (in the curve) and then lit it different to give some texture to the steel, it is rather dull grey as it is. Nice composition. 6</td>', 'Should have cleaned it more thoroughly (in the curve) and then lit it different to give some texture to the steel, it is rather dull grey as it is. Nice composition. 6', '2003-08-27 11:54:16.000000', NULL, 1),
(401155, 35003, 5603, '<td valign="top">Is that a real dog or is it stuffed?  Stuffed animals don''t get haircuts. The numerous tags on the collar are distracting me.  All your photos distract me and I''m very upset.  I KNOW that is your blue brush and not the dog''s. <br/>Who put the blonde highlights on the dog?  This is not normal.</td>', 'Is that a real dog or is it stuffed?  Stuffed animals don''t get haircuts. The numerous tags on the collar are distracting me.  All your photos distract me and I''m very upset.  I KNOW that is your blue brush and not the dog''s. Who put the blonde highlights on the dog?  This is not normal.', '2003-08-27 11:54:36.000000', NULL, 1),
(401156, 34790, 11111, '<td valign="top">Neat, simple use of negative space. I''d like to see the colors more saturated. The top black thingie seems to fade too much into the background. Creative interpretation.</td>', 'Neat, simple use of negative space. I''d like to see the colors more saturated. The top black thingie seems to fade too much into the background. Creative interpretation.', '2003-08-27 11:54:37.000000', NULL, 1),
