(401158, 35017, 4008, '<td valign="top">a bit overexposed and flat lighting</td>', 'a bit overexposed and flat lighting', '2003-08-27 11:55:42.000000', NULL, 1),
(401160, 35083, 11111, '<td valign="top">Great action shot. I''d like to see it a little more in focus, though. Nice way to fill the frame.</td>', 'Great action shot. I''d like to see it a little more in focus, though. Nice way to fill the frame.', '2003-08-27 11:56:13.000000', NULL, 1),
