INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(402191, 35163, 4258, '<td valign="top">Very good composition - but handmade paper under yellow light looks blotchy, also since you dont dip fountain pens in ink having the bottle open seem being careless. Also some compression artifacts can be seen along the edge</td>', 'Very good composition - but handmade paper under yellow light looks blotchy, also since you dont dip fountain pens in ink having the bottle open seem being careless. Also some compression artifacts can be seen along the edge', '2003-08-28 00:56:50.000000', NULL, 1),
(402198, 35235, 6803, '<td valign="top">I would have liked to see the whole rear of the car...nice reflection</td>', 'I would have liked to see the whole rear of the car...nice reflection', '2003-08-28 01:03:47.000000', NULL, 1),
(402240, 35175, 10055, '<td valign="top">Let me see here, subject matter is good. I like that. But, get crazy with it. Let up on useing a flash. Be creative with other sourses of llighting and the objests will come to life. But then again, if this is what you were after in a shot. Great. This is kust me. Good luck.</td>', 'Let me see here, subject matter is good. I like that. But, get crazy with it. Let up on useing a flash. Be creative with other sourses of llighting and the objests will come to life. But then again, if this is what you were after in a shot. Great. This is kust me. Good luck.', '2003-08-28 01:47:14.000000', NULL, 1),
(402244, 35165, 10055, '<td valign="top">Very nice photo. Useing all kinds of elements is great.</td>', 'Very nice photo. Useing all kinds of elements is great.', '2003-08-28 01:49:18.000000', NULL, 1),
(402267, 34788, 4494, '<td valign="top">Great idea... Should have had the bubble in the middle since the rest of the level is, well, level. :)</td>', 'Great idea... Should have had the bubble in the middle since the rest of the level is, well, level. :)', '2003-08-28 02:17:07.000000', NULL, 1),
(402269, 35007, 4494, '<td valign="top">Pic is a little boring... Try using the wrench on a bolt or something like that to give it more interest.</td>', 'Pic is a little boring... Try using the wrench on a bolt or something like that to give it more interest.', '2003-08-28 02:18:20.000000', NULL, 1),
(402275, 35097, 4494, '<td valign="top">Pretty good... what would have been better is the drawing being a sketch of your real hand holding the pencil.  That would be GREAT.  Good job.</td>', 'Pretty good... what would have been better is the drawing being a sketch of your real hand holding the pencil.  That would be GREAT.  Good job.', '2003-08-28 02:21:22.000000', NULL, 1),
(402276, 34994, 4494, '<td valign="top">Great lighting, it looks like "ad quality".  Even more-so with the "Stanley" logo positioned like that.  Nice job.</td>', 'Great lighting, it looks like "ad quality".  Even more-so with the "Stanley" logo positioned like that.  Nice job.', '2003-08-28 02:25:28.000000', NULL, 1),
(402278, 35187, 4494, '<td valign="top">It''s a GREAT shot with perfect lighting and very interesting subjects... But, there''s no tools in the shot.  The pumps aren''t really tools.  You should still make this a Print for sale, it''s great!</td>', 'It''s a GREAT shot with perfect lighting and very interesting subjects... But, there''s no tools in the shot.  The pumps aren''t really tools.  You should still make this a Print for sale, it''s great!', '2003-08-28 02:28:11.000000', NULL, 1),
(402279, 35012, 2437, '<td valign="top">Good DOF, but  lighting is not that good</td>', 'Good DOF, but  lighting is not that good', '2003-08-28 02:28:19.000000', NULL, 1),
(402281, 35078, 4494, '<td valign="top">I love Cheetahs.  Great shot.   Make the shot a little bigger if possible.</td>', 'I love Cheetahs.  Great shot.   Make the shot a little bigger if possible.', '2003-08-28 02:30:16.000000', NULL, 1),
