(402850, 34710, 11073, '<td valign="top">ha :) that''s great! nice work...on the horse? and the shot.</td>', 'ha :) that''s great! nice work...on the horse? and the shot.', '2003-08-28 14:58:07.000000', NULL, 1),
(402851, 34579, 11073, '<td valign="top">the rain spout on the left distracts me a little...good shot and composition.</td>', 'the rain spout on the left distracts me a little...good shot and composition.', '2003-08-28 14:58:51.000000', NULL, 1),
(402852, 34957, 4008, '<td valign="top">A beatiful clear image and original view on tools. Good depth as well.</td>', 'A beatiful clear image and original view on tools. Good depth as well.', '2003-08-28 14:58:56.000000', NULL, 1),
