(402857, 34770, 5792, '<td valign="top">This is one of those images that plays tricks on the eyes. Painted sawblades are among the last remaining icons left from the golden age of the lumber industry.</td>', 'This is one of those images that plays tricks on the eyes. Painted sawblades are among the last remaining icons left from the golden age of the lumber industry.', '2003-08-28 15:01:39.000000', NULL, 1),
(402858, 35008, 4008, '<td valign="top">Good idead and play with colors. I think the angle of the small should have been slightly different to give more the impression that the small tool is really in between the mouth of the bigger one. A bit tighter crop to remove the left and some of the bottom left white would have made it stronger. 7</td>', 'Good idead and play with colors. I think the angle of the small should have been slightly different to give more the impression that the small tool is really in between the mouth of the bigger one. A bit tighter crop to remove the left and some of the bottom left white would have made it stronger. 7', '2003-08-28 15:01:43.000000', NULL, 1),
(402859, 34427, 9690, '<td valign="top">focus is soft</td>', 'focus is soft', '2003-08-28 15:01:55.000000', NULL, 1),
(402860, 34411, 9690, '<td valign="top">nice angle</td>', 'nice angle', '2003-08-28 15:02:12.000000', NULL, 1),
(402861, 35139, 9690, '<td valign="top">great shot.. love the textures and how well they come out... wonderful job</td>', 'great shot.. love the textures and how well they come out... wonderful job', '2003-08-28 15:02:42.000000', NULL, 1),
(402862, 34546, 4008, '<td valign="top">small improvement : crop away the orange spot in the bottom of the picture.</td>', 'small improvement : crop away the orange spot in the bottom of the picture.', '2003-08-28 15:03:10.000000', NULL, 1),
