(402866, 35079, 9690, '<td valign="top">pic seems fuzzy</td>', 'pic seems fuzzy', '2003-08-28 15:04:10.000000', NULL, 1),
(402867, 34811, 9643, '<td valign="top">Clever and I like the black and white on this one very much.  Great job arranging all of the lenses.</td>', 'Clever and I like the black and white on this one very much.  Great job arranging all of the lenses.', '2003-08-28 15:05:54.000000', NULL, 1),
(402868, 34809, 11073, '<td valign="top">i would have liked to see a different angle.  I''m spending too much time trying to figure out what''s what and the like to recognize and appreciate.  The lighting is good, as well as the dof.  the eye glass "stem" is a distracting in the upper left as well.  The different colors are nice and add interest.</td>', 'i would have liked to see a different angle.  I''m spending too much time trying to figure out what''s what and the like to recognize and appreciate.  The lighting is good, as well as the dof.  the eye glass "stem" is a distracting in the upper left as well.  The different colors are nice and add interest.', '2003-08-28 15:06:04.000000', NULL, 1),
(402870, 34547, 9690, '<td valign="top">if those fingers arent real, they sure look like it... Hey, nice way to work a PF reference into the title!!!!</td>', 'if those fingers arent real, they sure look like it... Hey, nice way to work a PF reference into the title!!!!', '2003-08-28 15:06:13.000000', NULL, 1),
