(403994, 34524, 4008, '<td valign="top">not enough depth of field</td>', 'not enough depth of field', '2003-08-29 16:04:52.000000', NULL, 1),
(404013, 35139, 4008, '<td valign="top">Very special color and lighting. Strong through simplicity. At first I thought he was holding the hammer rather strange, as if it was going to slip from his hand, but then I saw your title. No 10 because the title is needed to fully appreciate the picture. 9</td>', 'Very special color and lighting. Strong through simplicity. At first I thought he was holding the hammer rather strange, as if it was going to slip from his hand, but then I saw your title. No 10 because the title is needed to fully appreciate the picture. 9', '2003-08-29 16:46:02.000000', NULL, 1),
(404014, 34818, 3280, '<td valign="top">Excellent shot, I will certainly be interested in finding out exactly what this actually is.  One of the weeks best.</td>', 'Excellent shot, I will certainly be interested in finding out exactly what this actually is.  One of the weeks best.', '2003-08-29 16:46:54.000000', NULL, 1),
(404015, 35021, 4008, '<td valign="top">Great image, he is not really welding is he ? Then I would expect the light to be so bright that the rest would have been black. I guess it is one of those sparkling firework sticks ? Doesn\''t need the big star effect. Crop away the green light. Good idea and execution. 8</td>', 'Great image, he is not really welding is he ? Then I would expect the light to be so bright that the rest would have been black. I guess it is one of those sparkling firework sticks ? Doesn\''t need the big star effect. Crop away the green light. Good idea and execution. 8', '2003-08-29 16:47:02.000000', NULL, 1),
(404016, 34453, 3280, '<td valign="top">Great shot, VERY realistic looking blood and that is hard to do.  Unless of course you used REAL blood!!</td>', 'Great shot, VERY realistic looking blood and that is hard to do.  Unless of course you used REAL blood!!', '2003-08-29 16:47:55.000000', NULL, 1),
(404018, 35247, 4008, '<td valign="top">crazy enough to become good. Very different. Thanks for breaking the monotony. I also like the light.  8</td>', 'crazy enough to become good. Very different. Thanks for breaking the monotony. I also like the light.  8', '2003-08-29 16:49:15.000000', NULL, 1),
(404019, 35232, 4008, '<td valign="top">I like the DOF and the light. The highlights are in the right place while still providing attractive contrasts to emphasise the strength of the tool. I only would have liked to be able to see what kind of tool it is, the only recognisable shape is the one vaguely in the back. 8</td>', 'I like the DOF and the light. The highlights are in the right place while still providing attractive contrasts to emphasise the strength of the tool. I only would have liked to be able to see what kind of tool it is, the only recognisable shape is the one vaguely in the back. 8', '2003-08-29 16:50:27.000000', NULL, 1),
(404020, 34550, 4008, '<td valign="top">very original and good picture. 9</td>', 'very original and good picture. 9', '2003-08-29 16:51:58.000000', NULL, 1),
(404029, 34688, 11135, '<td valign="top">I''m not sure why, and it it possible that part of the problem is my computer monitor, but it looks as though the entire picture has a little bit of a haze over it. I do not see a pure black in the entire picture. If you went into photoshop and tweaked it a little bit, you may be able to improve the tonal qualities of this picture.</td>', 'I''m not sure why, and it it possible that part of the problem is my computer monitor, but it looks as though the entire picture has a little bit of a haze over it. I do not see a pure black in the entire picture. If you went into photoshop and tweaked it a little bit, you may be able to improve the tonal qualities of this picture.', '2003-08-29 17:11:23.000000', NULL, 1);
