(404420, 35190, 10084, '<td valign="top">Great composition. Love the blurring on this piece. Beautiful color of the stars captured.</td>', 'Great composition. Love the blurring on this piece. Beautiful color of the stars captured.', '2003-08-30 01:21:33.000000', NULL, 1),
(404423, 35045, 11073, '<td valign="top">cool idea and good execution.</td>', 'cool idea and good execution.', '2003-08-30 01:31:24.000000', NULL, 1),
