(404425, 35229, 11073, '<td valign="top">Somehow, someway this shot keeps my interest.  I haven''t liked any similar to this near as much.  The "dirt?" on the screwdriver is great and adds authenticity to your title.  cool shot.</td>', 'Somehow, someway this shot keeps my interest.  I haven''t liked any similar to this near as much.  The "dirt?" on the screwdriver is great and adds authenticity to your title.  cool shot.', '2003-08-30 01:33:29.000000', NULL, 1),
(404427, 35165, 11073, '<td valign="top">ooohhh pretty...and it makes me thirsty! =`) ....lemme crack some mondavi here....ahhhhhh.....okay, now I can appreciate this pic even more.  The lighting is wonderful, and the arrangement of the items is superb.  Great table to use as a backdrop.  The glass even has the bubbles.  good dof too!  Did I mention that I like this =`)  CHEERS TO YA!</td>', 'ooohhh pretty...and it makes me thirsty! =`) ....lemme crack some mondavi here....ahhhhhh.....okay, now I can appreciate this pic even more.  The lighting is wonderful, and the arrangement of the items is superb.  Great table to use as a backdrop.  The glass even has the bubbles.  good dof too!  Did I mention that I like this =`)  CHEERS TO YA!', '2003-08-30 01:38:06.000000', NULL, 1),
(404435, 34547, 9412, '<td valign="top">WONDERFUL idea!  That is amazingly creative.</td>', 'WONDERFUL idea!  That is amazingly creative.', '2003-08-30 02:01:16.000000', NULL, 1),
(404440, 35121, 9906, '<td valign="top">This is a very cool shot. Nice DOF, but the focus is wrong though.  The background is nice and crisp at the curve, but the abacus and hand are out of focus.  I''m assuming of course that you wanted the focus to be the hand meeting the abacus.  I wanna know what the bacground is...</td>', 'This is a very cool shot. Nice DOF, but the focus is wrong though.  The background is nice and crisp at the curve, but the abacus and hand are out of focus.  I''m assuming of course that you wanted the focus to be the hand meeting the abacus.  I wanna know what the bacground is...', '2003-08-30 02:31:05.000000', NULL, 1),
(404441, 35064, 9906, '<td valign="top">This is an interesting shot that IMHO would have been better without the cracking of the...  Nice and crisp image!</td>', 'This is an interesting shot that IMHO would have been better without the cracking of the...  Nice and crisp image!', '2003-08-30 02:32:47.000000', NULL, 1),
(404442, 34561, 9906, '<td valign="top">The blue around the clock face makes the bacground look edited out....</td>', 'The blue around the clock face makes the bacground look edited out....', '2003-08-30 02:34:33.000000', NULL, 1),
