(404454, 35169, 4258, '<td valign="top">Interesting experiment with control of DoF</td>', 'Interesting experiment with control of DoF', '2003-08-30 03:00:56.000000', NULL, 1),
(404464, 34965, 9027, '<td valign="top">i like the perspective. nice glowing colors also.</td>', 'i like the perspective. nice glowing colors also.', '2003-08-30 03:18:31.000000', NULL, 1),
(404465, 34616, 9027, '<td valign="top">maybe it was a downcast day, but image could use some contrast to sharpen it a bit. :o)</td>', 'maybe it was a downcast day, but image could use some contrast to sharpen it a bit. :o)', '2003-08-30 03:19:22.000000', NULL, 1),
(404466, 34655, 9027, '<td valign="top">a lot of tools all over, but the clamp thing gives you a focal point. good job.</td>', 'a lot of tools all over, but the clamp thing gives you a focal point. good job.', '2003-08-30 03:21:04.000000', NULL, 1),
(404467, 34590, 9027, '<td valign="top">nice. i like the contrast between the delicate plant and the tough, hard edged nail.</td>', 'nice. i like the contrast between the delicate plant and the tough, hard edged nail.', '2003-08-30 03:22:47.000000', NULL, 1),
(404468, 35233, 9027, '<td valign="top">i like the rusted tools. your setup makes for a very graphic composition. the border is a bit heavy though. seems to fight with tools.</td>', 'i like the rusted tools. your setup makes for a very graphic composition. the border is a bit heavy though. seems to fight with tools.', '2003-08-30 03:24:09.000000', NULL, 1),
(404469, 35163, 9027, '<td valign="top">it''s great to see a different approach besides the typical tools. seems to be a yellow overcast on whole image. perhaps, desaturating the yellow a little would help. then again, maybe it was the glow from a lamp or something. :o)</td>', 'it''s great to see a different approach besides the typical tools. seems to be a yellow overcast on whole image. perhaps, desaturating the yellow a little would help. then again, maybe it was the glow from a lamp or something. :o)', '2003-08-30 03:26:39.000000', NULL, 1),
(404470, 35232, 9027, '<td valign="top">great composition. good focus.</td>', 'great composition. good focus.', '2003-08-30 03:27:17.000000', NULL, 1),
(404471, 34940, 9027, '<td valign="top">could use more lighting (background seems grey/grungy) or you could adjust the contrast a little. nice perspective on the tool.</td>', 'could use more lighting (background seems grey/grungy) or you could adjust the contrast a little. nice perspective on the tool.', '2003-08-30 03:29:09.000000', NULL, 1),
(404473, 35184, 9027, '<td valign="top">is that a magnifier or mirror? anyway, nice crisp image. definitely keeps my interest.</td>', 'is that a magnifier or mirror? anyway, nice crisp image. definitely keeps my interest.', '2003-08-30 03:31:18.000000', NULL, 1),
(404475, 35035, 9027, '<td valign="top">nice interpretation. looks like a swan! could use a bit more focus though.</td>', 'nice interpretation. looks like a swan! could use a bit more focus though.', '2003-08-30 03:32:45.000000', NULL, 1),
(404483, 35210, 10084, '<td valign="top">Great image. Gives off a blue collar worker feeling. I like it. Love the gloved hand holding the tools. "10"</td>', 'Great image. Gives off a blue collar worker feeling. I like it. Love the gloved hand holding the tools. "10"', '2003-08-30 03:46:32.000000', NULL, 1),
(404484, 35239, 10084, '<td valign="top">Good composition. The lighting is great. Subtle shapes of the guitar - beautiful.</td>', 'Good composition. The lighting is great. Subtle shapes of the guitar - beautiful.', '2003-08-30 03:48:09.000000', NULL, 1),
(404485, 35064, 10084, '<td valign="top">Very nice image. The cracked egg give the photo a very strong point of interest. Love the details. Great focus.</td>', 'Very nice image. The cracked egg give the photo a very strong point of interest. Love the details. Great focus.', '2003-08-30 03:50:10.000000', NULL, 1),
(404491, 35244, 10084, '<td valign="top">Beautiful image your took. Red handle gives the composition some color. Love the blurring motion that you achieved. Great photo.</td>', 'Beautiful image your took. Red handle gives the composition some color. Love the blurring motion that you achieved. Great photo.', '2003-08-30 04:16:27.000000', NULL, 1),
(404496, 35091, 10420, '<td valign="top">This photo is fun to look at. Like the colour and clarity. 10</td>', 'This photo is fun to look at. Like the colour and clarity. 10', '2003-08-30 04:27:12.000000', NULL, 1),
(404498, 34703, 10420, '<td valign="top">Great catch. Nice colour and sharpness. 10</td>', 'Great catch. Nice colour and sharpness. 10', '2003-08-30 04:27:57.000000', NULL, 1),
(404499, 34573, 10420, '<td valign="top">Very nice arrangement. I like how clean this is. You should get a ribbon for this. 10</td>', 'Very nice arrangement. I like how clean this is. You should get a ribbon for this. 10', '2003-08-30 04:28:37.000000', NULL, 1),
