(404503, 34957, 10420, '<td valign="top">Wonderful idea. Nice crop. Could have been sharper all over. 9</td>', 'Wonderful idea. Nice crop. Could have been sharper all over. 9', '2003-08-30 04:32:42.000000', NULL, 1),
