(404535, 34548, 9327, '<td valign="top">great action shot! I love the sparks! its a tool you know because of this effect. so execution is great!</td>', 'great action shot! I love the sparks! its a tool you know because of this effect. so execution is great!', '2003-08-30 07:16:24.000000', NULL, 1),
(404536, 34560, 11073, '<td valign="top">good colors and background.</td>', 'good colors and background.', '2003-08-30 07:16:37.000000', NULL, 1),
(404537, 35083, 11073, '<td valign="top">I''m feelin it.</td>', 'I''m feelin it.', '2003-08-30 07:17:05.000000', NULL, 1),
(404538, 34475, 11073, '<td valign="top">whoa, easy partner...i''m with ya on too much gov''t! =`)  good composition, lighting and background.  The West Virginia Aluminum ( ducktape ) I think would work better out of the wrapper to lend a more rugged look which is i think what you''re going for.  Go get em!</td>', 'whoa, easy partner...i''m with ya on too much gov''t! =`)  good composition, lighting and background.  The West Virginia Aluminum ( ducktape ) I think would work better out of the wrapper to lend a more rugged look which is i think what you''re going for.  Go get em!', '2003-08-30 07:20:02.000000', NULL, 1),
