(404895, 35126, 8125, '<td valign="top">Mmm, yummy - what''s for dinner!?!  Something is catching my attention (besides the pizza)..  Looks like a little bit of flash glare above the pizza, or could that be room lighting?</td>', 'Mmm, yummy - what''s for dinner!?!  Something is catching my attention (besides the pizza)..  Looks like a little bit of flash glare above the pizza, or could that be room lighting?', '2003-08-30 20:07:59.000000', NULL, 1),
(404898, 35021, 8125, '<td valign="top">I really like this shot - the only thing I might suggest is not having the center glare going to the picture edges...  (not sure what that is ''technically'' called).  The smaller sparks look great and the welder adds interest to the picture.</td>', 'I really like this shot - the only thing I might suggest is not having the center glare going to the picture edges...  (not sure what that is ''technically'' called).  The smaller sparks look great and the welder adds interest to the picture.', '2003-08-30 20:09:39.000000', NULL, 1),
(404901, 34876, 8125, '<td valign="top">Nice job!</td>', 'Nice job!', '2003-08-30 20:11:53.000000', NULL, 1),
(404902, 35159, 8125, '<td valign="top">The image seems a little dark - but I like your idea.  I might like to see this with a little more of the bottle showing.  It took a second glance to see what was happening in the picture.</td>', 'The image seems a little dark - but I like your idea.  I might like to see this with a little more of the bottle showing.  It took a second glance to see what was happening in the picture.', '2003-08-30 20:13:37.000000', NULL, 1),
