(404904, 34589, 10084, '<td valign="top">You were able to make a boring subject very interesting. Composition is absoletely beautiful. Crop is perfect. Love the line on the stretched out tape goint to the corner. I like that you used b&amp;w, it gives the picture great impact.</td>', 'You were able to make a boring subject very interesting. Composition is absoletely beautiful. Crop is perfect. Love the line on the stretched out tape goint to the corner. I like that you used b&w, it gives the picture great impact.', '2003-08-30 20:16:03.000000', NULL, 1),
(404905, 35124, 8125, '<td valign="top">This picture is well composed; a little more of the scene to the right and no text might be better??</td>', 'This picture is well composed; a little more of the scene to the right and no text might be better??', '2003-08-30 20:16:17.000000', NULL, 1),
