INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(405496, 35227, 7969, '<td valign="top">I think your shot is creative, it is a good idea.  I would like to see it a tad darker, just curious what it would look like (may not be an improvement). Great work.</td>', 'I think your shot is creative, it is a good idea.  I would like to see it a tad darker, just curious what it would look like (may not be an improvement). Great work.', '2003-09-01 00:15:42.000000', NULL, 1),
(405497, 34818, 6504, '<td valign="top">Wait a minute!!  What is that?    Very creative, for sure.   Nice young man for a model.</td>', 'Wait a minute!!  What is that?    Very creative, for sure.   Nice young man for a model.', '2003-09-01 00:15:45.000000', NULL, 1),
(405499, 34779, 6504, '<td valign="top">This picture makes me want to pick up one of these tools and feel it.  The colors, especially the reddish handle is excelletn.  The clarity and lighting is very very good.</td>', 'This picture makes me want to pick up one of these tools and feel it.  The colors, especially the reddish handle is excelletn.  The clarity and lighting is very very good.', '2003-09-01 00:17:01.000000', NULL, 1),
(405500, 35146, 7778, '<td valign="top">Finally, an entry that''s ''more'' than a depiction of a tool! The eye is even placed where it ought to be placed, given the ''facial'' composition. I have no doubt that this photo has much to endure beyond the confines of this challenge.<br/> <br/>It seems the outlines (along tube and in the bends near the ear pieces) seems to suffer a little (from oversharpening?)<br/> <br/>Despite of this, the image is a refreshing take on what could have easily been a ''threshed'' topic and a ''sterile'' subject. Hilarious, creative and my choice for Blue Ribbon!</td>', 'Finally, an entry that''s ''more'' than a depiction of a tool! The eye is even placed where it ought to be placed, given the ''facial'' composition. I have no doubt that this photo has much to endure beyond the confines of this challenge. It seems the outlines (along tube and in the bends near the ear pieces) seems to suffer a little (from oversharpening?) Despite of this, the image is a refreshing take on what could have easily been a ''threshed'' topic and a ''sterile'' subject. Hilarious, creative and my choice for Blue Ribbon!', '2003-09-01 00:17:10.000000', NULL, 1),
(405501, 34926, 7969, '<td valign="top">I like how it looks like the measuring tape is floating.  And I think your shot will hit a chord with a lot of the males voters :  )  good job.</td>', 'I like how it looks like the measuring tape is floating.  And I think your shot will hit a chord with a lot of the males voters :  )  good job.', '2003-09-01 00:17:49.000000', NULL, 1),
(405502, 35247, 6504, '<td valign="top">huh??? Why bite the sander???</td>', 'huh??? Why bite the sander???', '2003-09-01 00:18:28.000000', NULL, 1),
(405503, 34988, 7969, '<td valign="top">This shot lacks some technical merit, but makes up for it by being a very good find.  Good eye!</td>', 'This shot lacks some technical merit, but makes up for it by being a very good find.  Good eye!', '2003-09-01 00:20:28.000000', NULL, 1),
(405506, 35078, 7969, '<td valign="top">How can anyone not love these cuties!! I am a sucker for animal shots, I am sure people will say ''not on topic'' I say a good shot is a good shot and should have a chance to be seen and appreciated.  Nice blurring of the grass, how did you blur some in foreground and in the background--lovely effect.</td>', 'How can anyone not love these cuties!! I am a sucker for animal shots, I am sure people will say ''not on topic'' I say a good shot is a good shot and should have a chance to be seen and appreciated.  Nice blurring of the grass, how did you blur some in foreground and in the background--lovely effect.', '2003-09-01 00:22:40.000000', NULL, 1),
(405507, 34444, 7969, '<td valign="top">I ''ve been trying to figure out what this is, I finally got it a fish! DUH!  Interesting find.</td>', 'I ''ve been trying to figure out what this is, I finally got it a fish! DUH!  Interesting find.', '2003-09-01 00:24:05.000000', NULL, 1),
(405509, 34547, 7969, '<td valign="top">YYYYIIICKK and OUCH</td>', 'YYYYIIICKK and OUCH', '2003-09-01 00:24:57.000000', NULL, 1),
(405768, 35182, 492, '<td valign="top">next time put the paper pad on a sheet of glass and away from the blue back ground so it become blur. The pad would of have the floating in mid air effect.</td>', 'next time put the paper pad on a sheet of glass and away from the blue back ground so it become blur. The pad would of have the floating in mid air effect.', '2003-09-01 02:00:18.000000', NULL, 1),
(405777, 34822, 492, '<td valign="top">Use more ambient lighting next time to elemanate the more black halo.<br/></td>', 'Use more ambient lighting next time to elemanate the more black halo.', '2003-09-01 02:02:11.000000', NULL, 1),
(405892, 35097, 8981, '<td valign="top">Very interesting!  I like the use of a sepia-tone and the composition here. Having a drawn hand and a real hand really adds something to the photo.  Nice job!</td>', 'Very interesting!  I like the use of a sepia-tone and the composition here. Having a drawn hand and a real hand really adds something to the photo.  Nice job!', '2003-09-01 03:52:33.000000', NULL, 1),
(405893, 35021, 8981, '<td valign="top">Wow!  That is amazing!  I love how you captured the sparks flying.  Very nice.</td>', 'Wow!  That is amazing!  I love how you captured the sparks flying.  Very nice.', '2003-09-01 03:53:43.000000', NULL, 1),
(405896, 34926, 8981, '<td valign="top">Nice idea, I really wanted to do something like this too.  I feel like the background is a little grainy though.</td>', 'Nice idea, I really wanted to do something like this too.  I feel like the background is a little grainy though.', '2003-09-01 03:55:53.000000', NULL, 1),
(405898, 35247, 8981, '<td valign="top">Ouch!  I like this idea, but I feel like maybe if the model had her hair a little more done the idea of the photo would have come through a little better.  The lighting is also a little bright on the left.  Great, innovative idea!</td>', 'Ouch!  I like this idea, but I feel like maybe if the model had her hair a little more done the idea of the photo would have come through a little better.  The lighting is also a little bright on the left.  Great, innovative idea!', '2003-09-01 03:59:10.000000', NULL, 1),
(405899, 34589, 8981, '<td valign="top">This is the ULTIMATE TOOL right here!  Definatly a clutz''s friend.  Great idea.  I like the composition.  The lighting is a little bright for me though.</td>', 'This is the ULTIMATE TOOL right here!  Definatly a clutz''s friend.  Great idea.  I like the composition.  The lighting is a little bright for me though.', '2003-09-01 04:00:46.000000', NULL, 1),
(406110, 35183, 5822, '<td valign="top">I  like the low-key and the contrasts here, but most of all I really like the way you''ve captured the textures of the tools and their solidity.  They appear to have weight to them.</td>', 'I  like the low-key and the contrasts here, but most of all I really like the way you''ve captured the textures of the tools and their solidity.  They appear to have weight to them.', '2003-09-01 11:31:59.000000', NULL, 1),
(406123, 34908, 5822, '<td valign="top">The lighting and duotones really make this shot for me.  They set a mood of cold sterility and along with the sharp and pointy medical instruments, send a bit of a shudder down my spine.  Composition is really good too...I like your arrangement.</td>', 'The lighting and duotones really make this shot for me.  They set a mood of cold sterility and along with the sharp and pointy medical instruments, send a bit of a shudder down my spine.  Composition is really good too...I like your arrangement.', '2003-09-01 11:45:08.000000', NULL, 1),
(406133, 34703, 8981, '<td valign="top">I really like the composition in this!  It makes me feel like I should go brush right now!</td>', 'I really like the composition in this!  It makes me feel like I should go brush right now!', '2003-09-01 11:58:01.000000', NULL, 1),
(406134, 34790, 6504, '<td valign="top">I am looking at this photo for a second time and I just noticed the steam.  I give it an extra point from my original vote.   9</td>', 'I am looking at this photo for a second time and I just noticed the steam.  I give it an extra point from my original vote.   9', '2003-09-01 11:59:10.000000', NULL, 1),
(406137, 34978, 8981, '<td valign="top">Wow, she''s pretty pricey!  Nice composition, and a good take on the challenge.</td>', 'Wow, she''s pretty pricey!  Nice composition, and a good take on the challenge.', '2003-09-01 12:00:44.000000', NULL, 1),
(406282, 34444, 11351, '<td valign="top">Gloves weren''t the main attraction in the picture (at least to me). I like the picture, but I don''t think this challenge is the best for that picture.</td>', 'Gloves weren''t the main attraction in the picture (at least to me). I like the picture, but I don''t think this challenge is the best for that picture.', '2003-09-01 13:33:08.000000', NULL, 1),
