(408003, 34788, 10196, '<td valign="top">Thank you for all the comments.<br/> <br/>There are actually two tools in the photo - the obvious water level and as a backdrop I used a screwdriver with an orange plastic handle. Three lights - one straight on and two diffused through a plastic bucket in which I had put the tools.<br/> <br/>First I took some pictures with the bubble in the middle but then thought it looked better w. the bubble on the side (in combination w. the backdrop also).</td>', 'Thank you for all the comments. There are actually two tools in the photo - the obvious water level and as a backdrop I used a screwdriver with an orange plastic handle. Three lights - one straight on and two diffused through a plastic bucket in which I had put the tools. First I took some pictures with the bubble in the middle but then thought it looked better w. the bubble on the side (in combination w. the backdrop also).', '2003-09-03 05:04:54.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
